CREATE DATABASE /*!32312 IF NOT EXISTS*/`db_control_sys` /*!40100 DEFAULT CHARACTER SET utf8 */;

USE `db_control_sys`;

/*Table structure for table `t_device` */

DROP TABLE IF EXISTS `t_device`;

CREATE TABLE `t_device` (
  `unit_type` varchar(2) DEFAULT NULL COMMENT '设备型号',
  `monitoring_ver` varchar(64) DEFAULT NULL COMMENT '监控软件版本号',
  `is_host` varchar(2) DEFAULT NULL COMMENT '是否是主机 0 从机 1主机',
  `Module_Firmware_Version_Number` varchar(128) DEFAULT NULL COMMENT '模组固件版本号',
  `end_time` varchar(32) DEFAULT NULL COMMENT '策略结束时间',
  `start_time` varchar(32) DEFAULT NULL COMMENT '策略开始时间',
  `mode` varchar(2) DEFAULT NULL COMMENT '策略开关 0 策略关闭 1策略开启 2单次（手动开关）',
  `id` varchar(32) NOT NULL COMMENT '设备ID',
  `station_id` varchar(20) DEFAULT NULL COMMENT '站点id',
  `lbs_station` varchar(100) DEFAULT NULL COMMENT '设备场景(后续用做站点名）',
  `station_name` varchar(100) DEFAULT NULL COMMENT '站点名称',
  `lbs_id` varchar(256) DEFAULT NULL COMMENT '设备编码ID',
  `project_id` varchar(32) DEFAULT NULL COMMENT '项目id',
  `company_id` varchar(32) DEFAULT NULL COMMENT '设备厂商ID:companyId',
  `delegate_id` varchar(32) DEFAULT NULL COMMENT '委托Id',
  `iot_device_id` varchar(64) DEFAULT NULL COMMENT 'iot平台的设备id，36位',
  `lbs_name` varchar(50) DEFAULT NULL COMMENT '设备名称',
  `lbs_sim` varchar(32) DEFAULT NULL COMMENT 'CCID:设备通讯号码，20位',
  `lbs_lng` float(20,5) DEFAULT NULL COMMENT '设备经度',
  `lbs_lat` float(20,5) DEFAULT NULL COMMENT '设备纬度',
  `lbs_type` varchar(10) DEFAULT NULL COMMENT '设备类型：微分布1，电梯2',
  `lbs_number` int(11) DEFAULT NULL COMMENT '设备数量',
  `region_id` varchar(32) DEFAULT NULL COMMENT '所属区域ID',
  `lbs_signal` varchar(512) DEFAULT NULL COMMENT '信号检测结果（373字节）',
  `lbs_report` varchar(256) DEFAULT NULL COMMENT '勘察报告：（含现场照片）',
  `lbs_completion` varchar(255) DEFAULT NULL COMMENT '竣工资料、确认单',
  `lbs_address` varchar(100) DEFAULT NULL COMMENT '设备地址',
  `frequency_band` varchar(32) DEFAULT NULL COMMENT '频段',
  `purpose` varchar(32) DEFAULT NULL COMMENT '目的',
  `lbs_area` float(10,2) DEFAULT NULL COMMENT '面积',
  `lbs_humi` int(11) DEFAULT NULL COMMENT '湿度',
  `lbs_temprature` int(11) DEFAULT NULL COMMENT '温度',
  `lbs_sheet` text COMMENT '安装(施工)图纸',
  `accept_id` varchar(32) DEFAULT NULL COMMENT '验收人员Id',
  `cell_id` varchar(30) DEFAULT NULL COMMENT '设备Cell-ID',
  `pci` varchar(16) DEFAULT NULL COMMENT 'PCI',
  `rsrp` varchar(255) DEFAULT '' COMMENT 'RSRP，信号接收强度',
  `snr` varchar(16) DEFAULT NULL COMMENT '信号质量',
  `prod_module` varchar(32) NOT NULL COMMENT '产品型号',
  `B_used` int(11) DEFAULT NULL COMMENT 'B是否启用：1启用，0未启用',
  `Hub_used` int(11) DEFAULT NULL COMMENT 'Hub是否启用：1启用，0未启用',
  `C1_used` int(11) DEFAULT NULL COMMENT 'C1是否启用：1启用，0未启用，电梯仅启用C1',
  `C2_used` int(11) DEFAULT NULL COMMENT 'C2是否启用：1启用，0未启用',
  `C3_used` int(11) DEFAULT NULL COMMENT 'C3是否启用：1启用，0未启用',
  `C4_used` int(11) DEFAULT NULL COMMENT 'C4是否启用：1启用，0未启用',
  `C5_used` int(11) DEFAULT NULL COMMENT 'C5是否启用：1启用，0未启用',
  `C6_used` int(11) DEFAULT NULL COMMENT 'C6是否启用：1启用，0未启用',
  `C7_used` int(11) DEFAULT NULL COMMENT 'C7是否启用：1启用，0未启用',
  `owner_name` varchar(255) DEFAULT '' COMMENT '业主姓名',
  `owner_mobile` varchar(20) DEFAULT '' COMMENT '业主电话',
  `installer` varchar(32) DEFAULT NULL COMMENT '施工联系人姓名',
  `installer_mobile` varchar(15) DEFAULT NULL COMMENT '施工联系人电话',
  `ops_name` varchar(32) DEFAULT NULL COMMENT '维护人姓名',
  `ops_mobile` varchar(15) DEFAULT NULL COMMENT '维护人电话',
  `power_status` varchar(10) DEFAULT NULL COMMENT '电源状态 五端 （0 关 1 开）00000、11111',
  `status` varchar(32) DEFAULT '333333' COMMENT '000000000正常',
  `ins_process` int(11) DEFAULT NULL COMMENT '0安装中（待验收） 1 验收通过',
  `report_period` int(11) DEFAULT NULL COMMENT '上报周期，单位10分钟。默认为0，不填写',
  `create_time` datetime DEFAULT NULL COMMENT '安装时间(安装施工时间)创建时间',
  `last_report_time` datetime DEFAULT NULL COMMENT '上报时间',
  `accept_time` datetime DEFAULT NULL COMMENT '验收通过时间',
  `ver` varchar(20) DEFAULT NULL COMMENT '版本号',
  `switch_setting` varchar(16) DEFAULT NULL COMMENT '设备定时开关策略',
  `self_excitation` int(11) DEFAULT NULL COMMENT '是否自激',
  `lbs_RA` varchar(256) DEFAULT NULL COMMENT 'RA信息164',
  `lbs_RD` varchar(64) DEFAULT NULL COMMENT 'RD信息20',
  `lbs_RE` varchar(1024) DEFAULT NULL COMMENT 'RE信息',
  `onLine_Proc` int(11) DEFAULT NULL COMMENT '1启用，0未启用',
  `statu_ex` varchar(16) DEFAULT NULL COMMENT '设备的真实状态',
  `is_delete` varchar(1) DEFAULT NULL COMMENT '设备是否被删除 0：未被删除   1：已被删除',
  `add_type` varchar(1) DEFAULT NULL COMMENT '添加方式 0 自动 1 手动',
  `rent_status` varchar(1) DEFAULT NULL COMMENT '租赁状态 0 未读 1 已租',
  `lbs_process` varchar(1) DEFAULT NULL COMMENT '设备的阶段 0 未采购 1 未安装 2 未调试 3 调试中 4 调试成功',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `QUERY_IOTDEVID` (`iot_device_id`) USING BTREE,
  KEY `IDX_STATIONID` (`station_id`) USING BTREE,
  FULLTEXT KEY `QUERY_DEVICE` (`project_id`,`company_id`,`lbs_type`,`prod_module`,`lbs_process`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='设备信息表';

